function csvRows(content){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<content.length;i++){let c=content[i];if(c==='"'){if(quoted&&content[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(!quoted&&(c===';'||c==='\t'||c===','&&content.slice(0,content.indexOf('\n')).includes(',')&&!content.slice(0,content.indexOf('\n')).includes(';'))){row.push(cell.trim());cell=''}else if(!quoted&&(c==='\n'||c==='\r')){if(c==='\r'&&content[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows}
document.getElementById('foodCsv').addEventListener('change',async e=>{let f=e.target.files[0],status=document.getElementById('foodImportStatus');if(!f)return;try{let rows=csvRows(await f.text()),headers=rows.shift().map(x=>x.toLocaleLowerCase('da-DK').replace(/^\ufeff/,'')),name=headers.findIndex(x=>/^(navn|name|food.?name|fødevare|food)$/.test(x)),kcal=headers.findIndex(x=>/kcal|energi.*kalor|energy.*calor/.test(x)),protein=headers.findIndex(x=>/protein/.test(x));if(name<0||kcal<0||protein<0)throw Error('Kolonnerne navn, kcal og protein mangler.');let imported=rows.map(r=>({name:r[name]||'',kcal:Number((r[kcal]||'').replace(',','.')),protein:Number((r[protein]||'').replace(',','.')),unit:/mælk|juice|drik/i.test(r[name]||'')?'ml':'g',brand:'Din importerede CSV'})).filter(x=>x.name&&x.kcal>0&&x.kcal<1000&&x.protein>=0&&x.protein<100).slice(0,5000);if(!imported.length)throw Error('Ingen gyldige fødevarer fundet.');let old=data.customFoods;data.customFoods=imported;try{save()}catch(err){data.customFoods=old;throw err}status.textContent=`${imported.length} fødevarer er importeret og kan søges lokalt.`;toast('Fødevarer importeret')}catch(err){status.textContent='Kunne ikke indlæse CSV: '+err.message}finally{e.target.value=''}});
function chooseProduct(index){let x=searchItems[index];if(!x)return;let liquid=x.unit==='ml';document.getElementById('foodResults').innerHTML=`<div class="card" style="margin-top:12px"><strong>${esc(x.name)}</strong><p class="foot">${Math.round(x.kcal)} kcal og ${Number(x.protein).toFixed(1)} g protein pr. 100 ${liquid?'ml':'g'}. ${liquid?'Liter regnes som 1000 ml.':'Vælg den vægt, du spiste.'} Kontrollér etiketten.</p><form id="productAmount" class="form"><label class="field">Mængde<input name="amount" type="number" min="0.01" max="10000" step="0.01" value="${liquid?'250':'100'}" required></label><label class="field">Enhed<select name="unit">${liquid?'<option value="ml">ml</option><option value="l">L</option>':'<option value="g">g</option><option value="kg">kg</option>'}</select></label><button class="button span">Føj til madloggen</button></form></div>`;document.getElementById('productAmount').addEventListener('submit',e=>{e.preventDefault();let amount=Number(e.target.elements.amount.value),unit=e.target.elements.unit.value;if(!Number.isFinite(amount)||amount<=0)return;let basis=amount*(unit==='l'||unit==='kg'?1000:1);data.meals.push({id:crypto.randomUUID(),date:today(),name:x.name+' · '+amount+' '+unit,kcal:Math.round(x.kcal*basis/100),protein:Math.round(x.protein*basis/100*10)/10});save();foodSearchStatus('Varen er føjet til madloggen.');toast('Vare gemt')})}
document.getElementById('foodSearchForm').addEventListener('submit',e=>{e.preventDefault();searchFood(e.target.elements.query.value.trim())});document.getElementById('exportData').onclick=()=>{let blob=new Blob([JSON.stringify({app:'HARPEX',version:1,exportedAt:new Date().toISOString(),data},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='harpex-data-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);document.getElementById('transferStatus').textContent='Dine data er eksporteret som en fil.'};document.getElementById('importData').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{let parsed=JSON.parse(await file.text()),d=parsed.data;if(!['HARPEX','PULS'].includes(parsed.app)||!d||!Array.isArray(d.events)||!Array.isArray(d.meals)||!Array.isArray(d.lifts)||!Array.isArray(d.progress)||typeof d.profile!=='object')throw Error();if(!confirm('Import erstatter de data, der allerede er gemt i denne app. Fortsæt?'))return;data={...initial,...d};save();document.getElementById('transferStatus').textContent='Dine data er importeret.'}catch{document.getElementById('transferStatus').textContent='Filen kunne ikke importeres. Vælg en HARPEX-eksportfil.'}finally{e.target.value=''}};if(data.profile.kcalGoal==null&&!data.energy)document.getElementById('setupPrompt')?.style.setProperty('display','block');if(!window.matchMedia('(display-mode: standalone)').matches&&!navigator.standalone)document.getElementById('installHint')?.style.setProperty('display','block');if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));function removeItem(key,id){data[key]=data[key].filter(x=>x.id!==id);save()}function addPreset(id){let p=data.presets.find(x=>x.id===id);if(p){data.meals.push({...p,id:crypto.randomUUID(),date:today()});save()}}let toastTimer;function toast(message='Gemt'){let el=document.getElementById('saveToast');el.textContent=message;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',2600)}let energyStatusTimer;function handle(id,fn){document.getElementById(id).addEventListener('submit',e=>{e.preventDefault();try{let f=e.currentTarget,o=Object.fromEntries(new FormData(f));fn(o,f);save();toast('Gemt')}catch(err){console.error('HARPEX formularfejl',err);toast('Kunne ikke gemme. Prøv igen.')}})}handle('eventForm',(o,f)=>{const error=activityTimingError(o.time,o.endTime,!!o.endsNextDay);if(error)throw Error(error);const {editId,...fields}=o;const activity={...fields,endsNextDay:!!o.endsNextDay,title:String(o.title||'').trim()||o.type,id:editId||crypto.randomUUID()};if(editId){const index=data.events.findIndex(e=>e.id===editId);if(index<0)throw Error('Aktiviteten findes ikke');data.events[index]={...data.events[index],...activity}}else data.events.push(activity);f.reset();f.elements.date.value=selectedDate;updateStrengthPicker();resetActivityEditor()});handle('liftForm',(o,f)=>{data.lifts.push({...o,id:crypto.randomUUID(),date:trainingDate,workout:STRENGTH_PLANS[currentMode()][workoutIndex][0]});f.reset()});handle('mealForm',(o,f)=>{let m={name:o.name.trim(),category:o.category,kcal:Number(o.kcal),protein:Number(o.protein),id:crypto.randomUUID(),date:today()};if(!o.presetOnly)data.meals.push(m);if(o.savePreset||o.presetOnly){data.presets.push({...m,id:crypto.randomUUID()});presetCategory=o.category}const only=!!o.presetOnly;f.reset();resetMealMode();if(only)selectFoodView('saved')});handle('recoveryForm',o=>{data.recovery[today()]={sleep:Number(o.sleep),energy:Number(o.energy),soreness:Number(o.soreness),general:Number(o.general),creatine:!!o.creatine}});handle('progressForm',(o,f)=>{data.progress.push({...o,id:crypto.randomUUID(),date:o.date||today()});f.reset()});document.getElementById('energyForm').addEventListener('submit',saveEnergyFromForm);function saveEnergyFromForm(e){e.preventDefault();let f=e.currentTarget||document.getElementById('energyForm');if(!f.reportValidity())return false;let status=document.getElementById('energySaveStatus');try{let o=Object.fromEntries(new FormData(f));data.energy={...o,age:Number(o.age),weight:Number(o.weight),height:Number(o.height),sportSessions:Number(o.sportSessions),strengthSessions:Number(o.strengthSessions),matchSessions:Number(o.matchSessions),useAsGoal:!!data.energy?.useAsGoal};save();showTab('profile');status.textContent='Beregningen er gemt. Se dit resultat lige nedenfor.';clearTimeout(energyStatusTimer);energyStatusTimer=setTimeout(()=>status.textContent='',3500);toast('Beregning gemt');document.getElementById('energyResult').scrollIntoView({behavior:'smooth',block:'center'})}catch(err){console.error('HARPEX energifejl',err);status.textContent='Kunne ikke gemme beregningen. Prøv igen.'}return false}document.getElementById('useCalendarCounts').onclick=()=>{let f=document.getElementById('energyForm'),events=data.events.filter(e=>e.date>=today()&&e.date<=dayOffset(6));f.elements.sportSessions.value=events.filter(e=>e.type==='Sportstræning').length;f.elements.strengthSessions.value=events.filter(e=>e.type==='Styrke').length;f.elements.matchSessions.value=events.filter(e=>e.type==='Kamp').length};{let f=document.getElementById('energyForm');if(data.energy)Object.entries(data.energy).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v});else{let last=data.progress.filter(x=>x.type==='Vægt (kg)').at(-1);if(last)f.elements.weight.value=last.value}}handle('profileForm',(_,f)=>{let o=Object.fromEntries(new FormData(f));data.profile={...data.profile,...o,kcalGoal:Number(o.kcalGoal),proteinGoal:Number(o.proteinGoal),equipment:[...f.elements.equipment.selectedOptions].map(x=>x.value)}});let pf=document.getElementById('profileForm');Object.entries(data.profile).forEach(([k,v])=>{if(k!=='equipment'&&pf.elements[k])pf.elements[k].value=v??''});[...pf.equipment.options].forEach(o=>o.selected=(data.profile.equipment||[]).includes(o.value));document.querySelector('#eventForm [name=date]').value=selectedDate;if(data.recovery[today()]){let r=data.recovery[today()],f=document.getElementById('recoveryForm');for(let k of ['sleep','energy','soreness','general'])f.elements[k].value=r[k];f.elements.creatine.checked=r.creatine}
const STRENGTH_PLANS={
  0:[['Upper A',['Supine MB Rebound|3|3|Medicinbold|Eksplosive armbøjninger · 3×3–5','Speed Bench Press|3|3','Bench Press|3|8|Vægtstang|DB bænkpres','Pull Ups|3|maks|Pull-up bar|Lat pulldown','DB Row|3|10','Biceps|2–3|8–12','Triceps|2–3|8–12']],['Lower A',['Squat Jump|3|3','BB Squat Jump|3|3','Full Squat|3|8','DB Staggered Stance RDL|3|10','Calf Raises|3|12–15','Core|2–3|sæt']],['Upper B',['Incline Bench Press|3|8|Vægtstang|Incline DB bænkpres','DB Row|3|10','Close Grip Bench Press|3|8','Pull Ups|3|maks|Pull-up bar|Lat pulldown','Lateral Raise|2–3|8–12','Biceps|2|8–12']],['Lower B',['Ankle Jump|3|3','Trap Bar Jump|3|3','Trap Bar Deadlift|3|8','DB Romanian Deadlift|3|10','Drop Jump|3|3','Core|2–3|sæt']]],
  1:[['Upper',['Supine MB Rebound|3|3|Medicinbold|Eksplosive armbøjninger · 3×3–5','Speed Bench Press|3|3','Bench Press|3|8','Pull Ups|3|maks|Pull-up bar|Lat pulldown','DB Row|3|10','Biceps|2–3|8–12','Triceps|2–3|8–12']],['Lower',['Squat Jump|3|3','BB Squat Jump|3|3','Full Squat|3|8','Trap Bar Deadlift|3|8','DB RDL|3|10','Core|2–3|sæt']],['Full Body Light',['Ankle Jump|3|3','Trap Bar Jump|3|3','Incline Bench|3|8','Elbow Out Row|3|10','Close Grip Bench|2–3|8','DB Staggered RDL|2–3|10']]],
  2:[['Upper · Full Body A',['Squat Jump|3|3','Full Squat|3|6–8','Bench Press|3|8','Pull Ups|3|maks|Pull-up bar|Lat pulldown','DB Staggered RDL|2–3|10','DB Row|2–3|10']],['Lower · Full Body B',['Trap Bar Jump|3|3','Trap Bar Deadlift|3|6–8','Incline Bench|3|8','Elbow Out Row|3|10','Close Grip Bench|2–3|8','Core|2–3|sæt']]]};
function gamesInWeek(date){let d=new Date(date+'T12:00:00'),offset=(d.getDay()+6)%7;d.setDate(d.getDate()-offset);let start=localDate(d);d.setDate(d.getDate()+6);let end=localDate(d);return data.events.filter(e=>e.type==='Kamp'&&e.date>=start&&e.date<=end).length}function currentMode(){return workoutMode==='auto'?Math.min(2,gamesInWeek(trainingDate)):Number(workoutMode)}
function workoutExercise(raw){let [name,sets,reps,equipment,alternative]=raw.split('|');if(equipment&&(data.profile.equipment||[]).length&&!(data.profile.equipment||[]).includes(equipment)&&alternative){name=alternative;return {name,sets,reps,alternative:true}}return{name,sets,reps,alternative:false}}
function renderWorkout(){let mode=currentMode(),plans=STRENGTH_PLANS[mode],choice=document.getElementById('workoutChoice');document.getElementById('gameCount').value=workoutMode;document.getElementById('trainingDate').value=trainingDate;if(workoutIndex>=plans.length)workoutIndex=0;choice.innerHTML=plans.map((p,i)=>`<option value="${i}" ${i===workoutIndex?'selected':''}>${i+1}. ${p[0]}</option>`).join('');document.getElementById('planHint').textContent=`${mode} kamp(e) de næste syv dage: ${plans.length} styrkepas. Vælg en øvelse nedenfor og gem dens sæt, reps og kg.`;document.getElementById('workoutExercises').innerHTML=plans[workoutIndex][1].map((raw,i)=>{let x=workoutExercise(raw),last=data.lifts.filter(l=>l.date===trainingDate&&l.exercise===x.name).at(-1);return `<div class="exercise-entry"><div><strong>${esc(x.name)}</strong><small>${esc(x.sets)} sæt × ${esc(x.reps)} reps${x.alternative?' · tilpasset dit udstyr':''}${last?` · Gemt i dag: ${esc(last.sets)} × ${esc(last.reps)}${last.kg?` · ${esc(last.kg)} kg`:''}`:''}</small></div><form class="exerciseForm" data-index="${i}"><label>Sæt<input name="sets" aria-label="Sæt for ${esc(x.name)}" type="number" min="1" value="${parseInt(x.sets,10)||3}" required></label><label>Reps<input name="reps" aria-label="Reps for ${esc(x.name)}" type="number" min="1" value="${parseInt(x.reps,10)||1}" required></label><label>Kg<input name="kg" aria-label="Kg for ${esc(x.name)}" type="number" min="0" step="0.5" placeholder="valgfrit"></label><button type="submit" class="button secondary">Gem øvelse</button></form></div>`}).join('')}
document.addEventListener('submit',e=>{let f=e.target;if(!f.matches('.exerciseForm'))return;e.preventDefault();let raw=STRENGTH_PLANS[currentMode()][workoutIndex][1][Number(f.dataset.index)],x=workoutExercise(raw),sets=Number(f.elements.sets.value),reps=Number(f.elements.reps.value),kg=f.elements.kg.value;if(!x.name||!Number.isFinite(sets)||sets<1||!Number.isFinite(reps)||reps<1||kg!==''&&(!Number.isFinite(Number(kg))||Number(kg)<0)){toast('Tjek sæt, reps og kg');return}try{data.lifts.push({id:crypto.randomUUID(),date:trainingDate,exercise:x.name,workout:STRENGTH_PLANS[currentMode()][workoutIndex][0],sets,reps,kg:kg===''?'':Number(kg)});saveExerciseForm(f);toast(x.name+' gemt')}catch(err){console.error('HARPEX øvelsesfejl',err);toast('Øvelsen kunne ikke gemmes')}});
function renderWeightProjection(){let el=document.getElementById('weightProjection'),e=estimateEnergy();if(!e){el.innerHTML='<p class="foot">Udfyld alder, vægt, højde og din hverdag i Profil for at se, hvad dit kaloriemål teoretisk svarer til pr. uge.</p>';document.getElementById('weightProjectionHome').innerHTML=el.innerHTML;return}let maintenance=e.average-e.components.surplus,goal=currentKcalGoal()||e.average,surplus=goal-maintenance,grams=Math.round(surplus*7/7700*1000); el.innerHTML=`<p>Hvis du i gennemsnit spiser <strong>${goal} kcal om dagen</strong> i en uge, er det cirka ${surplus>=0?`${surplus} kcal over`:`${-surplus} kcal under`} dit beregnede vedligehold på ${maintenance} kcal/dag.</p><p><strong>Rent matematisk: ${surplus>0?`omtrent ${grams} g (${(grams/1000).toFixed(2).replace('.',',')} kg) pr. uge`:surplus<0?`cirka ${Math.abs(grams)} g mindre energi end vedligehold pr. uge`:'omtrent vedligehold'}.</strong></p><p class="foot">Dette er ikke et løfte om faktisk vægtændring; væske, vækst, træning og ændret energiforbrug kan give et helt andet resultat. ${e.youth?'For unge er beregningen ekstra usikker.':''} Sammenlign vægtmålinger over 2–4 uger.</p>`;document.getElementById('weightProjectionHome').innerHTML=el.innerHTML}

document.getElementById('trainingDate').addEventListener('change',e=>{trainingDate=e.target.value||today();localStorage.setItem('puls-training-date',trainingDate);workoutIndex=0;render()});document.getElementById('gameCount').addEventListener('change',e=>{workoutMode=e.target.value;workoutIndex=0;renderWorkout()});document.getElementById('workoutChoice').addEventListener('change',e=>{workoutIndex=Number(e.target.value);renderWorkout()});
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let action=b.dataset.action,value=b.dataset.value;if(action==='tab')showTab(value);if(action==='addOnDate')document.getElementById('eventForm').scrollIntoView({behavior:'smooth',block:'center'});if(action==='prevMonth'||action==='nextMonth'||action==='thisMonth'){let d=action==='thisMonth'?new Date(today()+'T12:00:00'):new Date(monthAnchor+'T12:00:00');if(action!=='thisMonth')d.setMonth(d.getMonth()+(action==='prevMonth'?-1:1));selectedDate=localDate(d);monthAnchor=selectedDate.slice(0,7)+'-01';weekAnchor=weekStart(selectedDate);monthAnchor=selectedDate.slice(0,7)+'-01';localStorage.setItem('puls-selected-date',selectedDate);document.querySelector('#eventForm [name=date]').value=selectedDate;updateStrengthPicker();render()}if(action==='prevWeek'||action==='nextWeek'||action==='thisWeek'){selectedDate=action==='thisWeek'?today():shiftDate(selectedDate,action==='prevWeek'?-7:7);weekAnchor=weekStart(selectedDate);monthAnchor=selectedDate.slice(0,7)+'-01';monthAnchor=selectedDate.slice(0,7)+'-01';localStorage.setItem('puls-selected-date',selectedDate);document.querySelector('#eventForm [name=date]').value=selectedDate;updateStrengthPicker();render()}if(action==='dayTrain'){trainingDate=selectedDate;localStorage.setItem('puls-training-date',trainingDate);render();showTab('train')}if(action==='next'){let n=data.events.find(x=>x.id===value);if(n){selectedDate=n.date;weekAnchor=weekStart(selectedDate);monthAnchor=selectedDate.slice(0,7)+'-01';localStorage.setItem('puls-selected-date',selectedDate);document.querySelector('#eventForm [name=date]').value=n.date;updateStrengthPicker();if(n.type==='Styrke'){trainingDate=n.date;localStorage.setItem('puls-training-date',trainingDate);workoutMode='auto';let index=STRENGTH_PLANS[currentMode()].findIndex(p=>p[0]===n.title);workoutIndex=Math.max(0,index);showTab('train')}else showTab('plan');render()}}if(action==='date'){selectedDate=value;weekAnchor=weekStart(selectedDate);monthAnchor=selectedDate.slice(0,7)+'-01';localStorage.setItem('puls-selected-date',selectedDate);document.querySelector('#eventForm [name=date]').value=selectedDate;updateStrengthPicker();render()}if(action==='remove'){removeItem(b.dataset.key,value);toast('Slettet')}if(action==='preset'){addPreset(value);toast('Måltid gemt')}if(action==='idea'){addIdea(value);toast('Måltid gemt')}if(action==='category')setIdeaCategory(value);if(action==='more')showMoreIdeas();if(action==='product')chooseProduct(Number(value));if(action==='exercise'){let raw=STRENGTH_PLANS[currentMode()][workoutIndex][1][Number(value)],x=workoutExercise(raw),f=document.getElementById('liftForm');f.elements.exercise.value=x.name;f.elements.sets.value=parseInt(x.sets,10)||3;f.elements.reps.value=parseInt(x.reps,10)||1;showTab('train');f.elements.kg.focus();toast('Øvelse valgt · angiv vægt og gem')}});
document.addEventListener('click',e=>{if(e.target.id==='applyEnergy'){data.energy.useAsGoal=!data.energy.useAsGoal;save()}});

function updateStrengthPicker(){let f=document.getElementById('eventForm'),isStrength=f.elements.type.value==='Styrke',picker=document.getElementById('strengthPicker'),list=document.getElementById('strengthEventChoice');picker.hidden=!isStrength;document.getElementById('activityTitleField').hidden=isStrength;f.elements.title.readOnly=isStrength;f.elements.title.required=isStrength;document.getElementById('activityTitleLabel').textContent='Titel (valgfri)';if(isStrength){let mode=Math.min(2,gamesInWeek(f.elements.date.value||today())),plans=STRENGTH_PLANS[mode];list.innerHTML=plans.map(p=>`<option value="${esc(p[0])}">${esc(p[0])}</option>`).join('');f.elements.title.value=plans[0][0]}else if(STRENGTH_PLANS[0].concat(STRENGTH_PLANS[1],STRENGTH_PLANS[2]).some(p=>p[0]===f.elements.title.value))f.elements.title.value=''}
document.querySelector('#eventForm [name=type]').addEventListener('change',updateStrengthPicker);document.querySelector('#eventForm [name=date]').addEventListener('change',updateStrengthPicker);document.getElementById('strengthEventChoice').addEventListener('change',e=>{document.getElementById('eventForm').elements.title.value=e.target.value});updateStrengthPicker();

function renderMonthCalendar(){let first=new Date(monthAnchor+'T12:00:00'),start=shiftDate(monthAnchor,-(first.getDay()+6)%7),end=new Date(first);end.setMonth(end.getMonth()+1);let count=Math.ceil(((end-first)/86400000+(first.getDay()+6)%7)/7)*7;document.getElementById('monthLabel').textContent=first.toLocaleDateString('da-DK',{month:'long',year:'numeric'});document.getElementById('monthCalendar').innerHTML=['Man','Tir','Ons','Tor','Fre','Lør','Søn'].map(x=>`<span class="month-weekday">${x}</span>`).join('')+Array.from({length:count},(_,i)=>{let date=shiftDate(start,i),events=data.events.filter(e=>e.date===date),lifts=data.lifts.filter(l=>l.date===date);return `<button type="button" class="month-day ${date.slice(0,7)!==monthAnchor.slice(0,7)?'other':''} ${date===selectedDate?'selected':''}" data-action="date" data-value="${date}" aria-label="${dateText(date)}: ${events.length} aktiviteter, ${lifts.length} øvelser" aria-pressed="${date===selectedDate}"><strong>${Number(date.slice(-2))}</strong>${events.slice(0,2).map(e=>`<small>${esc(e.type)}</small>`).join('')}${lifts.length?`<small>Styrke · ${lifts.length}</small>`:''}</button>`}).join('')}
function oneRepMax(l){let kg=Number(l.kg),reps=Number(l.reps);return Number.isFinite(kg)&&kg>0&&Number.isInteger(reps)&&reps>=1&&reps<=12?Math.round(kg*(1+(reps-1)/30)*10)/10:null}
function renderExerciseProgress(){const names=[...new Set(data.lifts.map(l=>l.exercise).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'da')),choice=document.getElementById('exerciseProgressChoice'),target=document.getElementById('exerciseProgress');if(!names.length){choice.innerHTML='<option>Ingen øvelser logget endnu</option>';choice.disabled=true;target.innerHTML='<p class="foot">Log øvelser under Træn for at se udviklingen her.</p>';return}choice.disabled=false;if(!names.includes(selectedExercise))selectedExercise=names[0];choice.innerHTML=names.map(name=>`<option value="${esc(name)}" ${name===selectedExercise?'selected':''}>${esc(name)}</option>`).join('');let entries=data.lifts.filter(l=>l.exercise===selectedExercise&&Number(l.kg)>0).slice().sort((a,b)=>a.date.localeCompare(b.date));if(!entries.length){target.innerHTML='<p class="foot">Denne øvelse har endnu ingen logget vægt. Kg vises, så snart du logger et løft.</p>';return}let valid=entries.filter(l=>oneRepMax(l)!==null),first=valid[0],last=valid.at(-1),series=valid.length?valid:entries,values=series.map(l=>oneRepMax(l)??Number(l.kg)),low=Math.min(...values),high=Math.max(...values),width=Math.max(360,series.length*62),points=values.map((v,i)=>`${36+(series.length===1?0:i*(width-72)/(series.length-1))},${140-(high===low?50:(v-low)/(high-low)*95)}`).join(' ');let change=first&&last&&first!==last?Math.round((oneRepMax(last)-oneRepMax(first))*10)/10:null;target.innerHTML=`<p><strong>${esc(selectedExercise)}</strong> · ${entries.length} loggede løft</p>${first?`<p>Estimeret 1RM: <strong>${oneRepMax(first)} → ${oneRepMax(last)} kg</strong>${change!==null?` (${change>=0?'+':''}${change} kg)`:''}</p>`:'<p>Ingen estimeret 1RM for denne øvelse endnu.</p>'}<div class="chart-scroll"><svg class="exercise-chart" viewBox="0 0 ${width} 180" role="img" aria-label="Udvikling for ${esc(selectedExercise)}"><line x1="36" y1="145" x2="${width-26}" y2="145" stroke="#69818b"/><polyline fill="none" stroke="#c5f569" stroke-width="3" points="${points}"/>${values.map((v,i)=>{let x=36+(series.length===1?0:i*(width-72)/(series.length-1)),y=140-(high===low?50:(v-low)/(high-low)*95);return `<circle cx="${x}" cy="${y}" r="5" fill="#c5f569"/><text x="${x}" y="${y-11}" fill="#eff5f7" font-size="11" text-anchor="middle">${v}</text>`}).join('')}</svg></div><div class="results">${entries.map(l=>`<div class="row"><span>${dateText(l.date)} · ${esc(l.kg)} kg × ${esc(l.reps)} reps</span><strong>${oneRepMax(l)===null?'–':oneRepMax(l)+' kg est. 1RM'}</strong></div>`).join('')}</div><p class="foot">1RM er et estimat ud fra kg og reps (1–12), ikke et løft du har testet. Hold øvelser og teknik sammenlignelige.</p>`}
document.getElementById('exerciseProgressChoice').addEventListener('change',e=>{selectedExercise=e.target.value;renderExerciseProgress()});
render();try{let active=sessionStorage.getItem('puls-active-tab');if(active&&document.getElementById(active)?.classList.contains('panel'))showTab(active)}catch{}
